def rows(a):
 return [dict(zip([c['name'] for c in assets[a]['columns']],r)) for r in assets[a]['rows']]
def excerpt(r): return '\n'.join(f'{k}: {json.dumps(v,ensure_ascii=False)}' for k,v in r.items())
# Each choice has one correct interpretation and two concept-specific misconception distractors.
checks={
'100':('A supplied unit test exits nonzero while integration succeeds. Which configuration and outcome demonstrate a blocking test gate?', 'Both supplied commands run in their jobs; promotion needs both jobs; neither test uses continue-on-error; the unit job fails and promotion is skipped.', 'Set continue-on-error on the failed test and still describe promotion as blocked.', 'Make promotion need only the successful integration job.', 'Failure must propagate from the command to its job and the dependent promotion. continue-on-error defeats this blocking requirement.', 'Promotion must require both test jobs, not just the successful one.'),
'101':('Which pull-request scope best supports focused infrastructure review?', 'One coherent EC2 change with clear intent, a focused diff and saved-plan evidence identifying the affected EC2 resource.', 'Several unrelated infrastructure changes grouped under one short commit message.', 'One EC2 change with clear intent but no saved-plan evidence of the affected resource.', 'A short message does not make unrelated changes coherent or reduce their review complexity.', 'Focused scope is not enough: the affected EC2 resource must be visible in saved-plan evidence.'),
'102':('What is the purpose of deliberately introducing a controlled failure in an availability experiment?', 'Verify whether the workload meets its availability requirements under failure.', 'Prove availability merely by counting instances that remain running.', 'Demonstrate that every component remains unchanged during the experiment.', 'Surviving components alone do not establish the required service behavior.', 'The experiment deliberately introduces a failure; unchanged components are not its success criterion.'),
'103':('A supplied exercise resource depends on another exercise resource. Which removal rule respects scope and dependencies?', 'Confirm approved exercise membership, remove the dependent resource before its prerequisite, and verify each deletion result.', 'Delete the prerequisite first and infer dependent removal from that request.', 'Delete similarly named resources without checking approved tags or stack membership.', 'Dependencies determine removal order; a deletion request is not proof of each resource removal.', 'Only resources identified by the supplied exercise membership or approved tags are in scope.'),
'104a':('An approved recovery session is unexpired, but the supplied backup-read test is denied. What does this establish?', 'The session is not ready: valid lifetime does not establish sufficient authorization.', 'The session is ready because its expiration time is still in the future.', 'The denied operation can be omitted from the readiness record.', 'Credential lifetime and authorization are separate requirements.', 'Access outcomes must be verified, not hidden by a valid lifetime.'),
'104b':('When must the approved rehearsal scope and stop conditions be recorded?', 'Before provisioning recovery resources or directing client test traffic.', 'After provisioning, but before the first client test request.', 'Only after the rehearsal finishes successfully.', 'Provisioning is already a rehearsal action; scope and stop conditions must precede it.', 'A later record does not bound the actions before they happen.'),
'106a':('A stop condition occurs in an Automation response. What must happen before any further action is allowed?', 'Request the approved stop operation and inspect execution state before allowing further actions.', 'Request stop and immediately allow the protected operation without inspecting state.', 'Ignore the stop condition because an approval step exists in the workflow.', 'A stop request alone does not replace inspecting execution state.', 'The approval step does not nullify a stop condition.'),
'106b':('Which response record accurately represents both successful and failed actions?', 'Execution details retain inputs, outputs and failure information; underlying actions are linked to CloudTrail request identity and operation evidence.', 'Record only successful steps because failed steps have no useful evidence.', 'Treat the intended workflow plan as proof that its AWS actions occurred.', 'Failure information and failed outcomes belong in the response record.', 'Actual request identity and operation evidence, not intention, attribute underlying actions.'),
'108a':('What does CloudTrail digest validation establish about unauthorized access or deletion?', 'It provides tamper evidence; it does not itself prevent unauthorized access or deletion.', 'It prevents all unauthorized deletion once validation passes.', 'It replaces access restrictions because signed digests control who can read logs.', 'Tamper detection is not preventive protection.', 'Signed digest validation does not itself impose access restrictions.'),
'108b':('During an active retention period, how do governance and compliance retention differ?', 'Governance bypass requires the necessary authorization and bypass request; compliance prevents deletion or shortening even by root.', 'A governance bypass request alone suffices without bypass authorization.', 'Root can shorten compliance retention during the retention period.', 'Governance bypass requires both the authorization and the request.', 'Compliance retention blocks deletion or shortening during the period even by root.'),
'110a':('Which sequence verifies a bootstrap and migration to an S3 Terraform backend?', 'Provision the protected bucket with local-state bootstrap first; change backend, perform the approved migration, and inspect state at the intended bucket/key.', 'Select the backend before its bucket exists and treat the configuration as migration proof.', 'Provision the bucket and assume state moved there without migration or destination inspection.', 'The bucket must exist before selection; declaring a destination does not verify migration.', 'Bucket existence is not evidence that state reached the intended bucket/key.'),
'110b':('A replacement plan shows the expected lifecycle order. What does that evidence establish about permission to apply?', 'It verifies replacement mechanics, but scope and impact approval are still required before a permitted apply.', 'The expected order itself authorizes the replacement.', 'A prevent_destroy rejection can be applied because it documents the protected resource.', 'Lifecycle plan evidence does not replace scope and impact approval.', 'A rejected plan is not a permitted apply.'),
'112':('Which restoration setup matches the required target and execution authority?', 'The supplied template and parameters, approved recovery credentials, and explicit isolated account and Region.', 'The supplied template with the current account and Region left unverified.', 'An arbitrary replacement template in the isolated account, regardless of required parameters.', 'Stack resources are provisioned under the selected account authority and Region; these must be explicit and approved.', 'Isolation does not replace using the supplied restoration template and required parameters.'),
'113':('The scan-policy check identifies an actionable unexcepted finding. Which gate result and evidence are required?', 'Return failure, block promotion because it requires check success, and retain the scan report and policy decision.', 'Return success so promotion can proceed, while keeping the report.', 'Return failure but allow promotion without requiring the scan-policy check to succeed.', 'Keeping a report does not make an actionable unexcepted finding a passing policy result.', 'A failing check only gates progression when promotion requires its success.'),
'114a':('After an approved correction to the first failed action, what should be verified before investigating later actions that did not run?', 'Retest and verify the corrected action succeeds with the intended input.', 'Investigate the skipped deployment first without retesting the failed action.', 'Treat approval of the correction as proof the action now succeeds.', 'Verify the corrected failure before investigating later dependent actions that did not run.', 'Approval does not replace execution evidence from the retest.'),
'114b':('Which pairing correctly distinguishes EC2 status-check boundaries?', 'System checks concern the underlying AWS host; instance checks concern instance software and networking.', 'System checks concern instance software; instance checks concern the underlying AWS host.', 'Both checks exclusively concern the underlying host.', 'These boundaries are reversed: system is host, instance is software and networking.', 'Instance checks cover the instance software and networking, not exclusively the underlying host.'),
'116':('A supplied Lambda smoke check fails. Which job-result reporting path preserves the release gate?', 'Call PutJobFailureResult and leave dependent progression blocked.', 'Call PutJobSuccessResult because the deployment operation completed.', 'Call PutJobSuccessResult now and check live behavior afterward.', 'Deployment completion does not justify success when live validation fails.', 'A passing smoke check must precede PutJobSuccessResult with the job ID.')}

def choice(key):
 q,c,w1,w2,f1,f2=checks[key]
 opts=[('a',c),('b',w1),('c',w2)]
 return {'prompt':q,'options':[{'option_id':i,'text':t} for i,t in opts],'selection':'single','shuffle':True}, {'correct_option_ids':['a'],'option_feedback':{'a':{'message':'Correct. '+c},'b':{'message':f1},'c':{'message':f2}}}

def classify(a, prompt, labels, judge, column, context='', selected=None, additions=()):
 data=rows(a); cols={c['name']:c for c in assets[a]['columns']}; items=[]; assignments={}; rm={}
 for n,r in enumerate(data):
  if selected is not None and n not in selected:continue
  i='item'+str(n+1); bucket=judge(r); role=cols[column]['semantic_role']; rm[bucket]=role
  # Full-row predicates are copied from the asset; occurrence is computed among exact duplicate rows.
  occurrence=sum(1 for previous in data[:n] if previous==r)
  items.append({'item_id':i,'text':context+'\n```text\n'+excerpt(r)+'\n```','source':{'asset_id':a,'row':{'where':r,'occurrence':occurrence},'column':column}});assignments[i]=bucket
 for n,(text,bucket) in enumerate(additions):
  i='review'+str(n+1);items.append({'item_id':i,'text':text});assignments[i]=bucket
 return {'prompt':prompt,'buckets':[{'bucket_id':i,'label':label} for i,label in labels.items()],'items':items},{'assignments':assignments,'role_map':rm,'item_feedback':{i:{'message':'Judgement: '+labels[b]+'. Compare the stated evidence with the required criterion.'} for i,b in assignments.items()}}

