out={k:p[k] for k in ['schema_version','path_id','batch_id']};out['kind']='interactions_part';out['tiles']=[]
for t in p['tiles']:
 entries=[]; seen=set(); numbered=[s for s in t['steps'] if s['type'] in ['check','hands_on']]
 for n,s in enumerate(numbered):
  cid=s['concept_ids'][0];x=bundles[cid];concept_index=t['concept_ids'].index(cid);num=t['tile_id'].split('.')[-1];key=num+('ab'[concept_index] if len(t['concept_ids'])>1 else '')
  public,grading=choice(key) if s['type']=='check' else practice(key)
  # Anchor ids may be shortened by the deterministic planner. Match bare capability via its standard hash shortening.
  def anchor_tag(cap):
   return cap if len(cap)<=64 else cap[:41]+'-'+hashlib.sha256(cap.encode()).hexdigest()[:8]
  measures=[]
  for an in s['anchors']:
   if '#assessment:' not in an:continue
   tag=an.split('#assessment:')[1]
   matches=[a for a in x['assessment_anchors'] if a['capability']==tag or anchor_tag(a['capability'])==tag]
   if not matches:
    # finlib uses a fixed maximum qualified id length; resolve the uniquely matching hash suffix without typing capability values.
    matches=[a for a in x['assessment_anchors'] if tag.endswith('-'+hashlib.sha256(a['capability'].encode()).hexdigest()[:8]) or a['capability'].startswith(tag.rsplit('-',1)[0])]
   assert len(matches)==1,(tag,matches)
   a=matches[0];measures.append({'concept_id':cid,'capability':a['capability'],'fact_ids':a['fact_ids']})
  feedback={'correct':{'message':'Correct. Your judgement follows the supplied evidence and the stated requirement.'},'incorrect':{'message':'Compare the evidence with the requirement rather than inferring success from a partial signal. '+x['practice_anchor']['success']},'hints':['Separate the observed outcome from what was merely intended.','Check every required condition, not just the most reassuring field.']}
  rems=[r for r in sc[t['tile_id']].get('remediation_steps',[]) if cid in r['concept_ids']]
  if rems:feedback['remediation_step_id']=rems[min(1 if cid in seen else 0,len(rems)-1)]['step_id']
  seen.add(cid)
  ix={'type':s['planned_interaction_type'],'interaction_id':'ix.'+s['step_id'],'difficulty':'intro' if n==0 else ('stretch' if n==len(numbered)-1 else 'core'),'grading_mode':'client','standalone':True,'anchors':s['anchors'],'measures':measures,'public':public,'grading':grading,'feedback':feedback}
  entries.append({'step_id':s['step_id'],'interaction':ix})
 out['tiles'].append({'tile_id':t['tile_id'],'interactions':entries})
(B/'interactions.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print('tiles',len(out['tiles']),'interactions',sum(len(t['interactions']) for t in out['tiles']))
